 public static void Build(){Directory.CreateDirectory(Dir);Directory.CreateDirectory(Output);var source=AssetDatabase.LoadAssetAtPath<GameObject>(Source);if(!source)throw new Exception("Existing high-detail Meshy sedan source required: "+Source);var src=UnityEngine.Object.Instantiate(source);Mesh car;Material carMat;try{var r=src.GetComponentsInChildren<MeshRenderer>().First(x=>x.name.StartsWith("Sedan "));var input=r.GetComponent<MeshFilter>().sharedMesh;car=UnityEngine.Object.Instantiate(input);var matrix=r.transform.localToWorldMatrix;var vertices=car.vertices.Select(v=>matrix.MultiplyPoint3x4(v)).ToArray();var min=vertices.Aggregate(Vector3.Min);var max=vertices.Aggregate(Vector3.Max);float length=Mathf.Max(max.x-min.x,max.z-min.z);var center=(min+max)*.5f;center.y=min.y;var yaw=max.x-min.x>max.z-min.z?Quaternion.Euler(0,-90,0):Quaternion.identity;for(int i=0;i<vertices.Length;i++)vertices[i]=yaw*(vertices[i]-center)*(4.6f/length);car.vertices=vertices;var normals=car.normals;var nm=matrix.inverse.transpose;for(int i=0;i<normals.Length;i++)normals[i]=(yaw*nm.MultiplyVector(normals[i])).normalized;car.normals=normals;car.RecalculateBounds();car.RecalculateTangents();car.name="Original Meshy sedan normalized units, full source topology";string path=Dir+"/source-sedan.mesh.asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(car,old);UnityEngine.Object.DestroyImmediate(car);car=old;}else AssetDatabase.CreateAsset(car,path);carMat=r.sharedMaterial;if(car.triangles.Length/3!=720238)throw new Exception("Original sedan topology count gate failed");}finally{UnityEngine.Object.DestroyImmediate(src);}
