 Box(root.transform,"FightFloor",new Vector3(0,-.06f,0),new Vector3(23,.12f,18),gravel);Box(root.transform,"Right outbuilding wall",new Vector3(6.4f,1.65f,1.5f),new Vector3(.22f,3.3f,12),wall);Box(root.transform,"Outbuilding roof",new Vector3(7.8f,3.32f,1.5f),new Vector3(3,.14f,12),wall);Box(root.transform,"Rose door",new Vector3(6.25f,1.15f,1.9f),new Vector3(.08f,2.3f,1.1f),rose);Box(root.transform,"Brick plinth",new Vector3(6.23f,.13f,1.5f),new Vector3(.12f,.26f,12),brick);Box(root.transform,"Left boundary",new Vector3(-10.6f,.9f,1.3f),new Vector3(.22f,1.8f,12),wall);
